import numpy as np

def generate_gpoints(recvec, gmax):
    '''Generate a grid of g-points for reciprocal space based on the provided lattice vectors.
    Parameters:
        recvec (np.ndarray): A 3x3 array representing the reciprocal lattice vectors.
        gmax (int): The maximum integer number of lattice points to include in one positive direction.
    Returns:
        np.ndarray: An array of shape (nk, 3) representing the grid of g-points.
    '''
    x = np.arange(-gmax, gmax + 1)
    yz = np.arange(-gmax, gmax + 1)

    gpoints_all = []
    for i in x:
        for j in yz:
            for k in yz:
                if (i == 0 and j < 0) or (i == 0 and k < 0):
                    continue
                elif i == 0 and j == 0 and k == 0:
                    continue
                else:
                    gpoints_all.append([i, j, k])

    return np.array(gpoints_all)

def isin(coord_test, coords):
    '''Check if a coordinate is in the list of coordinates.
    Parameters:
        coord_test (np.ndarray): A single coordinate to test.
        coords (np.ndarray): An array of coordinates.
    Returns:
        bool: True if coord_test is in coords, False otherwise.
    '''
    return np.any(np.all(coords == coord_test, axis=1))

