def orthogonalize(A):
    N = A.shape[0]
    B = np.zeros_like(A)
    for i in range(N):
        v = A[:, i]
        for j in range(i):
            projection = np.dot(v, B[:, j]) / np.dot(B[:, j], B[:, j])
            v -= projection * B[:, j]
        norm = np.linalg.norm(v)
        if norm != 0:
            B[:, i] = v / norm
    return B

