def U_i(r_i: np.ndarray, i: int, positions: np.ndarray, sigma: float, epsilon: float) -> float:
    U_i = 0.0
    for j in range(len(positions)):
        if j != i:
            r_ij = positions[j] - r_i
            U_ij = 4 * epsilon * ((sigma / np.linalg.norm(r_ij)) ** 12 - (sigma / np.linalg.norm(r_ij)) ** 6)
